public class CategoryPlot_getDomainAxisIndex_TriageGen1Test {

    private CategoryPlot plot;
    private CategoryDataset dataset;
    private CategoryItemRenderer renderer;
    private ValueAxis rangeAxis;

    @Before
    public void setUp() {
        dataset = Mockito.mock(CategoryDataset.class);
        rangeAxis = Mockito.mock(ValueAxis.class);
        renderer = Mockito.mock(CategoryItemRenderer.class);
        plot = new CategoryPlot(dataset, null, rangeAxis, renderer);
    }

    @Test
    public void testGetDomainAxisIndex_SingleAxis_ReturnsZero() {
        CategoryAxis axis = Mockito.mock(CategoryAxis.class);
        plot.setDomainAxis(axis);

        int index = plot.getDomainAxisIndex(axis);

        assertEquals("Index of the single domain axis should be 0", 0, index);
    }

    @Test
    public void testGetDomainAxisIndex_MultipleAxes_ReturnsCorrectIndex() {
        CategoryAxis axis0 = Mockito.mock(CategoryAxis.class);
        CategoryAxis axis1 = Mockito.mock(CategoryAxis.class);
        CategoryAxis axis2 = Mockito.mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis0, axis1, axis2});

        assertEquals("Index of the first axis should be 0", 0, plot.getDomainAxisIndex(axis0));
        assertEquals("Index of the second axis should be 1", 1, plot.getDomainAxisIndex(axis1));
        assertEquals("Index of the third axis should be 2", 2, plot.getDomainAxisIndex(axis2));
    }

    @Test
    public void testGetDomainAxisIndex_AxisNotFound_ReturnsNegativeOne() {
        CategoryAxis axisInPlot = Mockito.mock(CategoryAxis.class);
        CategoryAxis axisNotInPlot = Mockito.mock(CategoryAxis.class);

        plot.setDomainAxis(axisInPlot);

        int index = plot.getDomainAxisIndex(axisNotInPlot);

        assertEquals("Index of an axis not in the plot should be -1", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_EmptyAxes_ReturnsNegativeOne() {
        // Plot initialized with null domain axis in setUp
        CategoryAxis axis = Mockito.mock(CategoryAxis.class);

        int index = plot.getDomainAxisIndex(axis);

        assertEquals("Index in an empty domain axis list should be -1", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_NullAxis_ReturnsNegativeOne() {
        // Ensure there is at least one axis so the list isn't empty
        CategoryAxis axis = Mockito.mock(CategoryAxis.class);
        plot.setDomainAxis(axis);

        int index = plot.getDomainAxisIndex(null);

        assertEquals("Index of null axis should be -1", -1, index);
    }
}
